  const held = await required.assess({github: f.github, context: f.context, recordPath: f.recordPath, fetchImpl: f.fetchImpl, ignoreReceipt: true});
  assert.equal(held.cause, 'local_receipt_required', 'a repository that requires receipts is never reviewed by the fallback');
  assert.equal(artifactReads, reads);
}));

test('optional local review on the receipt-only route names the real condition instead of claiming a receipt is required', () => fixture(async f => {
  const keys = require('node:crypto').generateKeyPairSync('ed25519');
  const optional = createPolicy({...config, local_review: {mode: 'optional', reviewer_digest: require('./local-version.cjs').engineDigest(),
    max_age_seconds: 172800, keys: [{id: 'marker-fixture', issuer: 'ephemeral-fixture-runner', github_actor: 'contributor', revoked: false,
      public_key: keys.publicKey.export({type: 'spki', format: 'pem'})}]}});
  const assessment = await optional.assess({github: f.github, context: f.context, recordPath: f.recordPath, receiptOnly: true});
  assert.equal(assessment.decision, 'review_incomplete'); assert.equal(assessment.cause, 'local_receipt_unusable');
  assert.doesNotMatch(assessment.reason, /requires/); assert.match(assessment.reason, /optional/);
  const {body, NEXT_STEPS} = require('./incomplete.cjs');
  assert.match(NEXT_STEPS.local_receipt_unusable, /remove the `clouseau-local-review` marker/);
  const text = body({...assessment, receipt_notice: 'source'}, 'u');
  assert.match(text, /this receipt-only run did not review the change itself/); assert.doesNotMatch(text, /CI reviewed this change itself|requires a valid receipt/);
  assert.doesNotMatch(body(assessment, 'u'), /Local review receipt ignored/);
}));

// Opt-in maintainer attestation: an enrolled maintainer's receipt for a pull request by someone else (docs/local-review.md).
for (const controls of [false, true]) test(`controls=${controls}: a maintainer-attested receipt is accepted only for the exact signed author and pull request and never authorizes protected controls`, () => fixture(async f => {
  const crypto = require('node:crypto');
  const {issueReceipt} = require('./local-receipt.cjs');
  const {refresh} = require('./acceptance-sources.cjs');
  await f.assess();
  const seed = JSON.parse(fs.readFileSync(f.recordPath));
  const maintainer = crypto.generateKeyPairSync('ed25519');
  const outsider = crypto.generateKeyPairSync('ed25519');
  const pem = key => key.privateKey.export({type: 'pkcs8', format: 'pem'});
  const author = f.state.pr.user.login; const number = f.state.pr.number;
  const engine = {...require('./central-version.cjs').SOURCE, sha: 'e'.repeat(40), digest: require('./local-version.cjs').engineDigest()};
  // A receipt signed for exactly this configuration; `sign` picks the key and the attestation it carries.
  const mint = (trusted, {key = maintainer, attestation} = {}) => {
    const record = structuredClone(seed);
    record.snapshot.number = 0; record.snapshot.config_digest = digest(trusted); refresh(record.snapshot);
    record.result.snapshot = record.snapshot.digest; record.result.config_digest = record.snapshot.config_digest;
    record.result.usage = ['examiner', 'challenger'].flatMap(role => ['investigation', 'grading'].map(phase =>
      ({role, phase, harness: 'codex', session: `fictional-${role}-${phase}`, request_digest: digest(role),
        response_digest: digest(phase), transport_digest: digest({fixture_only: true})})));
    record.result.execution_digest = digest(record.result.usage);
    for (const item of record.result.reviews) item.report.snapshot = record.snapshot.digest;
    return issueReceipt({record, privateKey: pem(key), keyId: 'fixture', issuer: 'fixture-runner', reviewerSha: 'e'.repeat(40), attestation: structuredClone(attestation)});
  };
  const trustFor = attest => ({...config, ...(controls ? {sensitive_paths: [...config.sensitive_paths, 'src/upload.test.js']} : {}),
    local_review: {mode: 'required', reviewer_sha: 'e'.repeat(40), central_source: {...require('./central-version.cjs').SOURCE}, max_age_seconds: 172800,
      keys: [{id: 'fixture', issuer: 'fixture-runner', github_actor: 'maintainer', revoked: false, public_key: maintainer.publicKey.export({type: 'spki', format: 'pem'})}],
      ...(attest ? {attest} : {})}});
  const signed = {author, number, signer: 'maintainer'};
  const original = f.github.rest.repos.getContent;
  let served;
  f.github.rest.repos.getContent = async args => args.path === 'clouseau-review.json' ? {data: {
    encoding: 'base64', content: Buffer.from(JSON.stringify(served)).toString('base64'), size: JSON.stringify(served).length}} : original(args);
  f.state.pr.body = `Dependency update.\n<!-- clouseau-local-review:v1 ${'f'.repeat(40)} -->`;
  if (controls) f.state.comments = [{id: 87, user: {login: 'gaulatti', type: 'User'}, body: `/approve-intent ${f.state.pr.head.sha}`}];
  let providerCalls = 0; const reports = [];
  const assess = trusted => createPolicy(trusted, {engine}).assess({github: f.github, context: f.context, recordPath: f.recordPath,
    report: line => reports.push(line), fetchImpl: async () => {providerCalls++; throw new Error('CI AI must not be called');}});
  // Each attack is an ordinary ignored receipt with one fixed class; the PR is then reviewed by CI (here: required, so held).
  const ignored = async (trusted, bundle, reason) => {
    served = bundle; fs.rmSync(f.recordPath, {force: true});
    const result = await assess(trusted);
    assert.equal(result.receipt_notice, reason); assert.equal(result.review_source, undefined);
    assert.equal(result.decision, 'review_incomplete'); assert.equal(result.cause, 'local_receipt_required');
  };
  const trusted = trustFor({authors: [author]});
  // Default off: a receipt whose signer is not the author, with or without the claim, is ignored without the opt-in.
  await ignored(trustFor(undefined), mint(trustFor(undefined), {attestation: signed}), 'attestation');
  await ignored(trustFor(undefined), mint(trustFor(undefined)), 'author');
  // Allowlist that does not name this author, and an unrelated author's replay of this receipt.
  await ignored(trustFor({authors: ['someone-else']}), mint(trustFor({authors: ['someone-else']}), {attestation: signed}), 'attestation');
  f.state.pr.user.login = 'another-author';
  await ignored(trustFor({authors: [author, 'another-author']}), mint(trustFor({authors: [author, 'another-author']}), {attestation: signed}), 'attestation');
  await ignored(trustFor({authors: 'any'}), mint(trustFor({authors: 'any'}), {attestation: signed}), 'attestation');
  f.state.pr.user.login = author;
  // Wrong pull request number, forged signer, malformed claim, and a key that is not enrolled.
  await ignored(trusted, mint(trusted, {attestation: {...signed, number: number + 1}}), 'attestation');
  await ignored(trusted, mint(trusted, {attestation: {...signed, signer: 'someone-else'}}), 'attestation');
  await ignored(trusted, mint(trusted, {key: outsider, attestation: signed}), 'signature');
  const forged = mint(trusted, {attestation: signed}); forged.payload.attestation.author = 'another-author';
  await ignored(trusted, forged, 'signature');
  const extra = mint(trusted, {attestation: signed}); extra.payload.attestation.extra = true;
  await ignored(trusted, extra, 'signature');
  // The exact signed author and number are accepted, with zero CI AI calls and a maintainer-attested notice.
  served = mint(trusted, {attestation: signed}); fs.rmSync(f.recordPath, {force: true});
  const assessment = await assess(trusted);
  assert.equal(providerCalls, 0);
  if (controls) {
    // A receipt never authorizes protected controls; only the exact-head owner confirmation does, as for any receipt.
    assert.equal(assessment.decision, 'owner_decision');
    f.state.comments = [];
    fs.rmSync(f.recordPath, {force: true});
    const held = await assess(trusted);
    assert.equal(held.decision, 'review_incomplete'); assert.equal(held.cause, 'receipt_protected_controls');
    return;
  }
  assert.equal(assessment.decision, 'auto_approve', assessment.reason);
  assert.equal(assessment.review_source, 'maintainer_attested');
  assert.match(assessment.reason, /^Maintainer-attested passing local review/);
  assert.ok(reports.some(line => line === 'Maintainer-attested local Clouseau review verified. Signed by `maintainer` for the pull request by `contributor`. CI AI calls: 0.'));
  const summaries = [];
  const core = {info() {}, summary: {addRaw(text) {summaries.push(text); return this;}, async write() {}}};
  await createPolicy(trusted, {engine}).gate({github: f.github, context: f.context, core, recordPath: f.recordPath, assessment, nativeGate: true, wait: async () => {}});
  assert.equal(f.state.writes.filter(item => item.name === 'approve').length, 1);
  assert.ok(summaries.some(text => text.includes('Maintainer-attested local review (signed by `maintainer` for the pull request by `contributor`)')));
  // While independent CI is blocked the attested review is still named as such and approves nothing.
  f.state.failed = true; fs.rmSync(f.recordPath, {force: true});
  const blocked = await assess(trusted);
  assert.equal(blocked.decision, 'blocked_technical'); assert.equal(blocked.review_source, 'maintainer_attested');
  assert.ok(reports.some(line => line.startsWith('Maintainer-attested local Clouseau quality review verified.')));
  assert.equal(providerCalls, 0);
}));

// Exact revert (opt-in `exact_revert`): trees are judged by the engine from base-repository history, never by a model.
function revertWorld(f, {trees = ['2', '1', '0'], headTree = '1'} = {}) {
  const sha = letter => letter.repeat(39) + '7';
  const rows = trees.map((tree, index) => ({sha: index === 0 ? f.state.pr.base.sha : sha('abcdef'[index]), parents: index + 1 < trees.length ? [{sha: sha('abcdef'[index + 1])}] : [],
    commit: {tree: {sha: sha(tree)}}}));
  const world = {rows, headTree: sha(headTree), reads: 0};
  Object.assign(f.github.rest.repos, {
    getCommit: async () => {world.reads++; return {data: {sha: f.state.pr.head.sha, commit: {tree: {sha: world.headTree}}}};},
    compareCommitsWithBasehead: async () => ({data: {status: 'ahead', merge_base_commit: {sha: f.state.pr.base.sha}}}),
    listCommits: async () => ({data: world.rows}),
  });
  return world;
}

const REVERTING = {...config, exact_revert: {window: 5}};

test('exact_revert accepts a byte-identical earlier tree with zero AI calls and keeps every gate; unset it never runs', () => fixture(async f => {
  const world = revertWorld(f);
  // Unset: no history is read and the ordinary review runs.
  const ordinary = await f.assess();
  assert.equal(world.reads, 0);
  assert.ok(f.state.calls > 0);
  assert.equal(JSON.parse(fs.readFileSync(f.recordPath)).exact_revert, undefined);
  f.state.calls = 0;
  const policy = createPolicy(REVERTING);
  const reports = [];
  const assessment = await policy.assess({github: f.github, context: f.context, recordPath: f.recordPath, fetchImpl: f.fetchImpl, report: line => reports.push(line)});
  assert.equal(f.state.calls, 0);
  assert.equal(ordinary.record_digest === assessment.record_digest, false);
  assert.deepEqual([assessment.decision, assessment.review_source, assessment.provider_api_calls], ['auto_approve', 'exact_revert', 0]);
  assert.ok(reports.some(line => line.startsWith('Exact revert accepted without an AI review')));
  const core = {info() {}, summary: {addRaw() {return this;}, async write() {}}};
  const gate = value => policy.gate({github: f.github, context: f.context, core, recordPath: f.recordPath, assessment: value, nativeGate: true, wait: async () => {}});
  await gate(assessment);
  assert.equal(f.state.writes.filter(item => item.name === 'approve').length, 1);
  const posted = f.state.writes.find(item => item.name === 'create-ledger');
  assert.match(posted.args.body, /^<!-- clouseau-exact-revert:v1 -->\n## Clouseau exact revert/);
  // A second run updates its own notice in place.
  f.state.comments.push({id: 9, user: {login: 'github-actions[bot]'}, body: posted.args.body});
  f.state.writes.length = 0;
  await gate(assessment);
  assert.equal(f.state.writes.filter(item => item.name === 'update-ledger').length, 1);
  // Not an exact revert: the ordinary review runs (a tree absent from the history).
  world.headTree = 'f'.repeat(40);
  f.state.calls = 0;
  const miss = await policy.assess({github: f.github, context: f.context, recordPath: f.recordPath, fetchImpl: f.fetchImpl, report: line => reports.push(line)});
  assert.ok(f.state.calls > 0);
  assert.notEqual(miss.review_source, 'exact_revert');
  assert.ok(reports.some(line => line.startsWith('Exact revert not applied: the resulting tree is not a tree')));
}));

test('exact_revert gate refuses altered records, rewritten history, a moved head or base, changed verification and a disabled option', () => fixture(async f => {
  const world = revertWorld(f);
  const policy = createPolicy(REVERTING);
  const assessment = await policy.assess({github: f.github, context: f.context, recordPath: f.recordPath, fetchImpl: f.fetchImpl});
  const record = JSON.parse(fs.readFileSync(f.recordPath));
  const save = value => fs.writeFileSync(f.recordPath, JSON.stringify(value));
  const core = {info() {}, summary: {addRaw() {return this;}, async write() {}}};
  const gate = (value = assessment, which = policy) => which.gate({github: f.github, context: f.context, core, recordPath: f.recordPath, assessment: value, nativeGate: true, wait: async () => {}});
  const altered = structuredClone(record); altered.exact_revert.tree = 'f'.repeat(40); save(altered);
  await assert.rejects(gate(), /Stale or altered exact-revert record/);
  save(record);
  await assert.rejects(gate({...assessment, decision: 'owner_decision'}), /Stale or altered exact-revert record/);
  await assert.rejects(gate({...assessment, review_source: 'authenticated_local'}), /Stale or altered exact-revert record/);
  await assert.rejects(gate(assessment, createPolicy({...config, exact_revert: {window: 6}})), /Stale or altered exact-revert record/);
  await assert.rejects(gate(assessment, f.policy), /Stale or altered exact-revert record/);
  const original = world.rows; world.rows = original.map((row, index) => index === 1 ? {...row, commit: {tree: {sha: 'e'.repeat(40)}}} : row);
  await assert.rejects(gate(), /Exact-revert evidence changed/);
  world.rows = original;
  f.state.pr.head.sha = 'd'.repeat(40);
  await assert.rejects(gate(), /PR changed after exact-revert investigation/);
  f.state.pr.head.sha = assessment.head_sha;
  f.state.failed = true;
  await assert.rejects(gate(), /Verification changed after exact-revert/);
  f.state.failed = false;
  f.state.pr.base.sha = 'c'.repeat(40);
  await assert.rejects(gate());
  f.state.pr.base.sha = assessment.base_sha;
  assert.equal(f.state.writes.filter(item => item.name === 'approve').length, 0);
}));

test('exact_revert never waives protected controls: without the exact-head confirmation the ordinary review runs, with it the owner decision is exact', () => fixture(async f => {
  const filename = '.github/clouseau.json';
  f.github.rest.pulls.listFiles = async () => ({data: [{filename, status: 'modified', patch: '+protected control'}]});
  const content = f.github.rest.repos.getContent;
  f.github.rest.repos.getContent = args => content({...args, path: args.path === filename ? 'src/upload.test.js' : args.path});
  revertWorld(f);
  const policy = createPolicy(REVERTING);
  const run = () => policy.assess({github: f.github, context: f.context, recordPath: f.recordPath, fetchImpl: f.fetchImpl});
  const held = await run();
  assert.equal(held.decision, 'owner_decision');
  assert.notEqual(held.review_source, 'exact_revert');
  assert.ok(f.state.calls > 0);
  f.state.calls = 0;
  f.state.comments.push({id: 1, user: {login: 'gaulatti', type: 'User'}, body: `/approve-intent ${f.state.pr.head.sha}`});
  const exact = await run();
  assert.deepEqual([exact.decision, exact.review_source, f.state.calls], ['owner_decision', 'exact_revert', 0]);
  const core = {info() {}, summary: {addRaw() {return this;}, async write() {}}};
  await policy.gate({github: f.github, context: f.context, core, recordPath: f.recordPath, assessment: exact, nativeGate: true, wait: async () => {}});
  assert.equal(f.state.writes.filter(item => item.name === 'approve').length, 1);
  // The confirmation is bound to the head and can be withdrawn before the gate.
  f.state.comments.length = 0;
  await assert.rejects(policy.gate({github: f.github, context: f.context, core, recordPath: f.recordPath, assessment: exact, nativeGate: true, wait: async () => {}}),
    /owner authorization changed/);
}));

test('exact_revert is revalidated at the private owner merge write boundary', () => fixture(async f => {
  const world = revertWorld(f);
  const p = await privateOwnerFixture(f, false, {exact_revert: {window: 5}});
  assert.equal(p.assessment.review_source, 'exact_revert');
  await p.run(true);
  assert.deepEqual(f.state.writes.filter(w => ['approve', 'atomic'].includes(w.name)).map(w => w.name), ['approve', 'atomic']);
  assert.ok(world.reads >= 3);
}));

